INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('9898', 'tieflader-mit-container', 'Tieflader mit Container', (SELECT id FROM catalog_themes WHERE slug = 'city-action'), 'City Action', 'Tieflader mit abnehmbarem Baucontainer und klappbarer Rampe Realistisches Spiel: mobiler Container mit Büro, Pausenraum und Badezimmer Enthält PLAYMOBIL-Fahrerfigur, Schutzhelm, Feuerlöscher und Zubehör Fahrerkabine nach vorne klappbar mit Platz für zwei Figuren für realistischen Spielspaß Kompatibel mit PLAYMOBIL-Bagger (70442) und RC-Kran (70441)', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/tieflader-mit-container/9898.html", "breadcrumbs": ["Home", "Shop ...", "City Action"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
