INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('70955', 'museum', 'Museum', (SELECT id FROM catalog_themes WHERE slug = 'history'), 'History', 'Mittelalterliches Gebäude in authentischer Fachwerkoptik für kreative Museums- und Stadtgeschichten 125-teiliges History-Spielset mit zwei Figuren, Brunnen, Holztisch und historischen Werkzeugen Spinnrad, Schleifstein, Töpferscheibe und Webstuhl sorgen für realistische Mittelalter-Rollenspiele Ideal zum Erweitern einer mittelalterlichen Stadt und für fantasievolle Museumsführungen Kombinierbar mit weiteren History Sets und perfekt für kleine Geschichtsfans ab 4 Jahren', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/museum/70955.html", "breadcrumbs": ["Home", "Shop ...", "History"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
