INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('70947', 'westernladen-m.-wohnung', 'Westernladen m. Wohnung', (SELECT id FROM catalog_themes WHERE slug = 'western'), 'Western', 'PLAYMOBIL Westernladen mit Wohnung (70947) – detailreiches Western Spielset für echte Wildwest Abenteuer. Zweistöckiges Gebäude mit Laden unten und Wohnraum oben – perfekt für Deine PLAYMOBIL Western City. Umfangreiches Cowboy Spielzeug mit 2 Figuren, Waren und Zubehör. PLAYMOBIL Set ab 4 Jahren – ideal für kreatives Rollenspiel im PLAYMOBIL Wilder Westen. Kombinierbar mit Goldmine (70948) und Banditenversteck (1023) für noch mehr Western Spielzeug.', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/westernladen-m.-wohnung/70947.html", "breadcrumbs": ["Home", "Shop ...", "Western"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
