INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('70444', 'lkw-mit-wechselaufbau', 'LKW mit Wechselaufbau', (SELECT id FROM catalog_themes WHERE slug = 'city-action'), 'City Action', 'Baustellen-LKW mit austauschbarer Ladefläche für Sack- oder Schüttgut Mulde mit Hebevorrichtung und Rollen für schnelles Entladen Mit Anhänger, Werkzeugkiste, Benzinkanister, Verkehrskegeln und Zubehör Enthält PLAYMOBIL-Bauarbeiterfigur mit Helm und Handschuhen RC-fähiger LKW mit abnehmbarem Dach, erweiterbar mit RC-Modul (Art. 6914)', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/lkw-mit-wechselaufbau/70444.html", "breadcrumbs": ["Home", "Shop ...", "City Action"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
