INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('70948', 'goldmine', 'Goldmine', (SELECT id FROM catalog_themes WHERE slug = 'western'), 'Western', 'Erlebe spannende Abenteuer im Wilden Westen mit dem PLAYMOBIL-Goldmine-Spielset, inklusive versteckter Goldnuggets und funktionierendem Minenlorenwagen. Interaktive Einsturzfunktion mit herabfallenden Felsbrocken sorgt für realistischen Nervenkitzel bei jeder Goldsuche. Mit flackernder Grubenlampe (Batterie inklusive), Sprengbox und Dynamitstangen für actionreiches Spielvergnügen. Enthält 3 detaillierte PLAYMOBIL-Figuren, Tiere (Esel und Waschbären) sowie über 20 Zubehörteile für kreatives Erzählen. Perfekt für Kinder ab 5 Jahren – dieses realistische Goldminen-Spielset fördert Fantasie, Problemlösungsfähigkeiten und Teamarbeit.', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/goldmine/70948.html", "breadcrumbs": ["Home", "Shop ...", "Western"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
