INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('70570', 'polizei-gelaendewagen--verfolgung-des-schatzraeubers', 'Polizei-Geländewagen: Verfolgung des Schatzräubers', (SELECT id FROM catalog_themes WHERE slug = 'city-action'), 'City Action', 'Robuster Polizei-Offroader für actionreiche Verfolgungsjagden auf unwegsamem Gelände Räuber mit Motocross-Bike und Goldschatz sorgt für spannende Polizei-Abenteuer Handschellen, Funkgerät und Taschenlampe ermöglichen realistische Einsatzszenen Hohler Baumstumpf dient als cleveres Versteck für die gestohlene Beute Stinktier, Figuren und Zubehör fördern fantasievolle Rollenspiele ab 4 Jahren', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/polizei-gelaendewagen--verfolgung-des-schatzraeubers/70570.html", "breadcrumbs": ["Home", "Shop ...", "City Action"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
