INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('9887', 'betonmischer', 'Betonmischer', (SELECT id FROM catalog_themes WHERE slug = 'city-action'), 'City Action', 'Mix it up mit dem Betonmischer von PLAYMOBIL Volle Ladung Baustellen-Action! Der Betonmischer mit drehbarer Trommel und realistischer Kippfunktion bringt jede Menge Spielspaß auf Deine PLAYMOBIL-Baustelle. Ideal kombinierbar mit dem Seilbagger mit Bauteil (70442) oder dem RC-Baukran mit Bauteil (70441) für ein starkes Bau-Team!', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/betonmischer/9887.html", "breadcrumbs": ["Home", "Shop ...", "City Action"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
