INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('6530', 'familie-hauser', 'Familie Hauser', (SELECT id FROM catalog_themes WHERE slug = 'my-life'), 'My Life', 'Vier beliebte YouTube-Charaktere mit Anna, Lena, Nicole und Michael für fantasievolle Alltagsabenteuer Typische Outfits der Figuren sorgen für hohen Wiedererkennungswert bei Fans der Videoserie Ideal zum Nachspielen von Ausflügen, Urlauben, Geburtstagsfeiern und lustigen Familiengeschichten Fördert kreatives Rollenspiel, Erzählen eigener Geschichten und stundenlangen Spielspaß im Kinderzimmer Perfektes Geschenk für junge Fans ab 4 Jahren und alle, die Familienabenteuer lieben', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/familie-hauser/6530.html", "breadcrumbs": ["Home", "Shop ...", "My Life"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
