INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('6571', 'autowaschanlage', 'Autowaschanlage', (SELECT id FROM catalog_themes WHERE slug = 'my-life'), 'My Life', 'Realistische Spielzeug-Autowaschanlage mit echtem Wasser für spannenden Waschspaß im Kinderzimmer Rotierende Bürsten reinigen Fahrzeuge spielerisch und sorgen für authentische Waschstraßen-Abenteuer Einfache Bedienung mit Wasserpumpe und auswählbarem Waschprogramm für Kinder ab 4 Jahren Geeignet für viele Spielzeugautos bis 12,5 x 10,5 cm und perfekt für kleine Autoliebhaber Fördert kreatives Rollenspiel rund um Fahrzeuge, Waschen und realistische Alltagsszenen', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/autowaschanlage/6571.html", "breadcrumbs": ["Home", "Shop ...", "My Life"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
