INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('70441', 'rc-baukran-mit-bauteil', 'RC-Baukran mit Bauteil', (SELECT id FROM catalog_themes WHERE slug = 'city-action'), 'City Action', 'Ferngesteuerter Baustellenkran für realistische Bauabenteuer mit schweren Stahlträgern und präziser Steuerung IR-Fernbedienung mit Kanalwechselfunktion zur Steuerung von bis zu vier Kränen gleichzeitig Enthält zwei Bauarbeiterfiguren, Gitterpalette, Steine, Stahlträger, Bodenplatte und weiteres Bauzubehör Fördert Kreativität, Feinmotorik und fantasievolle Rollenspiele rund um große Baustellenprojekte Ideales Geschenk für kleine Baumeister ab 5 Jahren und Fans von Baustellen-Spielsets', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/rc-baukran-mit-bauteil/70441.html", "breadcrumbs": ["Home", "Shop ...", "City Action"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
