INSERT INTO catalog_sets (set_number, slug, name, theme_id, category_label, description, metadata) VALUES ('7350', 'unterwassermotor', 'Unterwassermotor', (SELECT id FROM catalog_themes WHERE slug = 'my-life'), 'My Life', 'PLAYMOBIL Unterwassermotor für realistische Fahrten mit kompatiblen Schiffen und Booten Bringt Bewegung in Wasserfahrzeuge und sorgt für dynamische Abenteuer in Häfen, Seen und Ozeanen Kompatibel mit allen aufrüstbaren PLAYMOBIL Wasserfahrzeugen für flexible Erweiterungen bestehender Sets Ideal für Schatzsuchen, Forschungsreisen, Rettungseinsätze und kreative maritime Spielgeschichten PLAYMOBIL PLUS Zubehör für mehr Realismus, Abwechslung und langanhaltenden Wasserspielspaß', '{"source_brand": "Playmobil", "source_url": "https://www.playmobil.com/de-de/unterwassermotor/7350.html", "breadcrumbs": ["Home", "Shop ...", "My Life"]}'::jsonb) ON CONFLICT (set_number) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, theme_id = EXCLUDED.theme_id, category_label = EXCLUDED.category_label, description = EXCLUDED.description, metadata = EXCLUDED.metadata;
